/* Renders the recorded verification evidence into the showcase page.
 * The data file is generated by scripts/build_site_data.py from real runs
 * (acceptance report + a live pytest run + the Chromium browser interaction run
 * + a live /api/health snapshot). */
(function () {
  'use strict';

  function el(tag, attrs, text) {
    var node = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (key) {
      if (key === 'class') node.className = attrs[key];
      else node.setAttribute(key, attrs[key]);
    });
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function setText(id, value) {
    var node = document.getElementById(id);
    if (node) node.textContent = value;
  }

  function renderShots(shots) {
    var host = document.getElementById('shots');
    host.textContent = '';
    shots.forEach(function (shot) {
      var figure = el('figure', { class: 'shot' });
      var link = el('a', { href: shot.file, target: '_blank', rel: 'noopener' });
      link.appendChild(el('img', { src: shot.file, alt: shot.caption, loading: 'lazy' }));
      figure.appendChild(link);
      figure.appendChild(el('figcaption', {}, shot.caption));
      host.appendChild(figure);
    });
  }

  function renderAcceptance(acc) {
    setText('acc-date', (acc.generated_at || '').replace('T', ' '));
    setText('acc-summary', acc.summary.pass + ' / ' + acc.summary.total + ' PASS');
    var checks = acc.cases.reduce(function (sum, c) { return sum + c.checks; }, 0);
    setText(
      'acc-detail',
      '共 ' + checks + ' 项校验，' + acc.summary.fail + ' 项失败；运行编号 ' + acc.run_id +
      '；seekdb ' + (acc.context.seekdb_version || '') + '，PowerContext ' + (acc.context.powercontext_version || '') +
      '，embedding ' + (acc.context.embedding_provider || '')
    );
    var body = document.querySelector('#acc-table tbody');
    body.textContent = '';
    acc.cases.forEach(function (c) {
      var row = el('tr');
      row.appendChild(el('td', { class: 'mono' }, c.id));
      row.appendChild(el('td', {}, c.title));
      row.appendChild(el('td', { class: c.status === 'PASS' ? 'status-pass' : 'status-fail' }, c.status));
      row.appendChild(el('td', {}, String(c.checks)));
      row.appendChild(el('td', {}, String(c.failed)));
      row.appendChild(el('td', {}, (c.duration_ms / 1000).toFixed(1) + 's'));
      body.appendChild(row);
    });
  }

  function renderBenchmarks(bench) {
    if (!bench) return;
    var w1 = document.getElementById('bench-w1');
    var w2 = document.getElementById('bench-w2');
    var mem = document.getElementById('bench-memory');
    if (bench.workflow) {
      var w = bench.workflow.w1;
      w1.textContent = '';
      [
        '问题数：' + w.questions + '（含中→英、英→中、术语与过滤用例）',
        '基线定位正确：' + w.baseline_correct + '/' + w.questions + '，但产出可点引用 0 条',
        'ResearchFlow top1 正确：' + w.rf_top1_correct + '/' + w.questions +
          '，top5 正确：' + w.rf_top5_correct + '/' + w.questions,
        'ResearchFlow 产出可点引用：' + w.rf_citations + '/' + w.questions +
          '，总耗时 ' + w.rf_ms_total + ' ms',
        '已知失败：1 条中文问题的正确块排在第 6 位（top_k=5 截断），已如实记录'
      ].forEach(function (line) { w1.appendChild(el('li', {}, line)); });

      var v = bench.workflow.w2;
      w2.textContent = '';
      [
        '基线从手工笔记恢复字段：' + v.baseline_recovered + '/' + v.baseline_total +
          '，需人工修正 ' + v.baseline_corrections + ' 条',
        'ResearchFlow 保存+跨进程恢复：' + (v.rf_total_ms / 1000).toFixed(1) +
          ' s，字段逐条精确，人工修正 ' + v.rf_corrections + ' 条',
        '基线无结构、无来源指针、不能跨会话恢复；ResearchFlow 三者皆具备'
      ].forEach(function (line) { w2.appendChild(el('li', {}, line)); });
    }
    if (bench.memory_zh) {
      var s = bench.memory_zh.summary;
      mem.textContent = '';
      [
        'PowerContext 自带 search_memory（fts5 unicode61）：' + s['pc_search_hit@5'] + '，且负例误报 1/1',
        '精确读取（全量 + 快照）：字段级 100%，但不具备检索能力',
        'ResearchFlow 本地 CJK 匹配 + kind 定向读取：hit@3 ' + s['local_hit@3'] +
          '，hit@1 ' + s['local_hit@1'] + '，负例误报 0/1',
        '结论：瓶颈在召回层（unicode61 不分中文 + 元提问词面零重叠），存储层无损'
      ].forEach(function (line) { mem.appendChild(el('li', {}, line)); });
    }
    if (bench.retrieval) {
      var tbody = document.querySelector('#bench-retrieval tbody');
      tbody.textContent = '';
      bench.retrieval.table.forEach(function (row) {
        var tr = el('tr');
        [row.provider, row.mode, row['recall@1'], row['recall@5'], row.mrr,
         row['page_acc@1'], row.latency_ms, row.false_positives].forEach(function (value) {
          tr.appendChild(el('td', {}, String(value)));
        });
        tbody.appendChild(tr);
      });
    }
  }

  function renderInteractions(itx) {
    if (!itx) return;
    setText('int-summary', itx.passed + ' / ' + (itx.passed + itx.failed) + ' PASS');
    setText(
      'int-detail',
      '记录于 ' + (itx.checked_at || '').replace('T', ' ').replace(/\.\d+Z$/, '') +
      ' 的 Chromium 真实运行；覆盖 ' + (itx.routes || []).length + ' 个页面、' +
      (itx.viewport_matrix || []).join(' / ') + ' px 视口；' + itx.failed + ' 项失败'
    );
  }

  function render(data) {
    setText('pytest-passed', data.pytest.passed + ' passed');
    setText(
      'pytest-detail',
      data.pytest.command + ' → ' + data.pytest.passed + ' 通过 / ' + data.pytest.failed + ' 失败 / ' +
      data.pytest.skipped + ' 跳过'
    );
    setText(
      'fact-seekdb',
      data.live.seekdb_version + ' @ ' + data.live.seekdb_endpoint +
      ' · 分析器 ' + data.live.fts_analyzer + ' · 集合 ' + data.live.collection +
      ' · 文档 ' + data.live.counts.documents + ' / 页 ' + data.live.counts.pages +
      ' / chunks ' + data.live.counts.chunks
    );
    setText(
      'fact-powercontext',
      'powercontext ' + data.live.powercontext_version + ' · Scope + Atomic Memory · ' +
      'embedding ' + data.live.embedding.provider + ' (' + data.live.embedding.dimension + ' 维)'
    );
    renderShots(data.screenshots);
    renderAcceptance(data.acceptance);
    renderInteractions(data.interactions);
    renderBenchmarks(data.benchmarks);

    var limits = document.getElementById('limitations');
    limits.textContent = '';
    data.limitations.forEach(function (text) { limits.appendChild(el('li', {}, text)); });

    setText(
      'footer-meta',
      '页面证据生成于 ' + data.generated_at.replace('T', ' ') + '；验收运行 ' + data.acceptance.run_id +
      '。所有截图与数字均来自真实运行，未使用模拟数据。'
    );
  }

  fetch('data/evidence.json')
    .then(function (response) {
      if (!response.ok) throw new Error('HTTP ' + response.status);
      return response.json();
    })
    .then(render)
    .catch(function (error) {
      setText('shots', '证据数据加载失败：' + error.message);
      setText('acc-summary', '不可用');
      setText('pytest-passed', '不可用');
      setText('int-summary', '不可用');
    });
})();
